package com.appdimens.games

import com.appdimens.games.core.GameMetrics
import com.appdimens.games.math.GameMath
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Kernel parity tests. Expectations generated by scripts/oracle.py
 * (canonical appdimens-dynamic 3.x math). Tolerance follows the family
 * convention (delta <= 0.05 for float32 paths).
 */
class GameMathKernelsTest {

    private fun m(w: Int, h: Int, sw: Int = 0, densityDpi: Int = 160): GameMetrics =
        GameMetrics.of(w, h, sw, densityDpi)

    private val phone = m(360, 800)
    private val land = m(800, 360)
    private val tablet = m(600, 960, densityDpi = 320)
    private val ref = m(300, 533)

    @Test fun scaled_16_phone_is19_2() {
        assertEquals(19.2f, GameMath.calculateScaledDp(16f, phone), 0.05f)
    }
    @Test fun scaledA_16_phone_matchesOracle() {
        assertEquals(19.768049f, GameMath.calculateScaledDp(16f, phone, applyAspectRatio = true), 0.05f)
    }
    @Test fun scaled_16_tablet_densityIndependent() {
        assertEquals(32.0f, GameMath.calculateScaledDp(16f, tablet), 0.05f)
    }
    @Test fun reference_window_identity() {
        assertEquals(100.0f, GameMath.calculateScaledDp(100f, ref), 0.05f)
        assertEquals(16.0f, GameMath.calculatePowerDp(16f, ref), 0.05f)
        assertEquals(16.0f, GameMath.calculateLogarithmicDp(16f, ref), 0.05f)
        assertEquals(16.0f, GameMath.calculateAutoDp(16f, ref), 0.05f)
        assertEquals(16.0f, GameMath.calculateInterpolatedDp(16f, ref), 0.05f)
    }
    @Test fun hdp_wdp_landscape_axes() {
        assertEquals(19.2f, GameMath.calculateScaledDp(16f, land, qualifier = com.appdimens.games.common.DpQualifier.HEIGHT), 0.05f)
        assertEquals(42.666667f, GameMath.calculateScaledDp(16f, land, qualifier = com.appdimens.games.common.DpQualifier.WIDTH), 0.05f)
    }
    @Test fun percent_literal_spaceW() {
        assertEquals(36.0f, GameMath.percentOfAxisDp(10f, phone, com.appdimens.games.common.DpQualifier.WIDTH), 0.05f)
    }
    @Test fun power_tablet_stevens() {
        assertEquals(80.726056f, GameMath.calculatePowerDp(48f, tablet), 0.05f)
    }
    @Test fun fluid_band_clamps_and_interpolates() {
        assertEquals(13.371429f, GameMath.calculateFluidDp(16f, phone), 0.05f)
        assertEquals(12.8f, GameMath.calculateFluidDp(16f, ref), 0.05f)      // below band → minV
        assertEquals(16.8f, GameMath.calculateFluidDp(16f, tablet), 0.05f)   // above band → maxV
    }
    @Test fun auto_transition_linear_then_log() {
        assertEquals(48.0f, GameMath.calculateAutoDp(40f, phone), 0.05f)     // linear ≤480
        assertEquals(69.383556f, GameMath.calculateAutoDp(40f, tablet), 0.05f)
    }
    @Test fun logarithmic_both_branches() {
        assertEquals(53.646431f, GameMath.calculateLogarithmicDp(50f, phone), 0.05f)
        assertEquals(45.537129f, GameMath.calculateLogarithmicDp(50f, m(240, 480)), 0.05f)
    }
    @Test fun interpolated_midpoint() {
        assertEquals(72.0f, GameMath.calculateInterpolatedDp(48f, tablet), 0.05f)
    }
    @Test fun diagonal_family_constant_parity() {
        // Published Dynamic test expectation: 50·√(300²+400²)/611.6305f
        assertEquals(40.874351f, GameMath.calculateDiagonalDp(50f, m(400, 300)), 0.05f)
        assertEquals(88.844051f, GameMath.calculateDiagonalDp(48f, tablet), 0.05f)
    }
    @Test fun perimeter_fit_fill_density() {
        assertEquals(89.891957f, GameMath.calculatePerimeterDp(48f, tablet), 0.05f)
        assertEquals(86.454034f, GameMath.calculateFitDp(48f, tablet), 0.05f)
        assertEquals(96.0f, GameMath.calculateFillDp(48f, tablet), 0.05f)
        assertEquals(96.0f, GameMath.calculateDensityDp(48f, tablet), 0.05f)
    }
    @Test fun px_conversion_uses_snapshot_density() {
        assertEquals(64.0f, GameMath.toPx(GameMath.calculateScaledDp(16f, tablet), tablet), 0.05f)
    }

    // ── Invariant (`i`) semantics ───────────────────────────────────────────
    @Test fun invariant_metrics_freeze_on_non_fullscreen_window() {
        val anchor = com.appdimens.games.core.GameScreen.invariantMetrics()
        val resized = GameMetrics.of(360, 600, isFullscreen = false)
        com.appdimens.games.core.GameScreen.update(resized)
        // Live path follows the resized window; invariant path stays on the fullscreen anchor.
        assertEquals(resized, com.appdimens.games.core.GameScreen.metrics())
        assertEquals(anchor.scale, com.appdimens.games.core.GameScreen.invariantMetrics().scale, 0f)
        com.appdimens.games.core.GameScreen.resetForTests()
    }
}
